package safety

import (
	"context"
	"encoding/json"
	"os"
	"testing"
	"time"

	"github.com/gitmoot/workspace-janitor/internal/collect"
	"github.com/gitmoot/workspace-janitor/internal/core"
)

// This is the immutable quarantine snapshot written by 5ee52f74 on
// 2026-10-21, not a digest generated by the implementation under test.
// Recollection is supplied at the existing observer boundary: no test opens
// the production path named in this historical receipt.
func TestRevalidateLegacyGitReceipt(t *testing.T) {
	raw, err := os.ReadFile("testdata/quarantined-git-v1.json")
	if err != nil {
		t.Fatal(err)
	}
	for _, scenario := range []string{"unchanged", "inode", "mode", "activity", "dirty", "active_job", "protected", "missing_activity", "unknown_digest", "altered_snapshot"} {
		t.Run(scenario, func(t *testing.T) {
			var saved, fresh core.Entry
			if err := json.Unmarshal(raw, &saved); err != nil {
				t.Fatal(err)
			}
			if err := json.Unmarshal(raw, &fresh); err != nil {
				t.Fatal(err)
			}
			fresh.Fingerprint = collect.Fingerprint(fresh)
			in := RevalidateInput{
				Action: core.Action{ID: "legacy", Path: saved.Path, Kind: core.ActionDeleteCandidate, FilesystemID: saved.FilesystemID},
				Now:    saved.ObservedAt.Add(4 * 24 * time.Hour),
			}
			switch scenario {
			case "inode":
				fresh.FilesystemID.Inode++
			case "mode":
				fresh.Ownership.Mode = "0700"
			case "activity":
				fresh.Git.LastActivity = fresh.Git.LastActivity.Add(time.Second)
			case "dirty":
				fresh.Git.DirtyFiles = 1
			case "active_job":
				in.Jobs = []JobRef{{ID: "live", State: JobRunning, Path: saved.Path, Owner: "fixture"}}
			case "protected":
				in.Policy.ProtectedPaths = []string{saved.Path}
			case "missing_activity":
				saved.Git.LastActivity = time.Time{}
			case "unknown_digest":
				saved.Fingerprint = "unknown"
			case "altered_snapshot":
				saved.Ownership.Mode = "0700"
			}
			in.Planned = saved
			in.Recollect = func(context.Context, string) (core.Entry, error) { return fresh, nil }
			verdict := Revalidate(context.Background(), in)
			if scenario == "unchanged" {
				if verdict.Refused() {
					t.Fatalf("unchanged legacy quarantine cannot expire: %+v", verdict.Protections)
				}
			} else if !verdict.Refused() {
				t.Fatalf("unsafe legacy receipt accepted for %s", scenario)
			}
			// Conversion must never replace the receipt with a live observation.
			if in.Planned.Fingerprint != saved.Fingerprint || in.Planned.Git.LastActivity != saved.Git.LastActivity {
				t.Fatal("historical snapshot was rewritten")
			}
		})
	}
}
